// What the Raccoon desktop app puts on the wire, as values this plugin can
// reproduce.
//
// The app's chat calls are made by a bundled CPython sidecar
// (`resources/box-agent-runtime/`), so its request is defined by Python code:
// the openai SDK 2.8.0 over httpx, plus a few headers of its own on top. None
// of that is JavaScript, and none of it is reached by reading the app's JS
// bundle — so the values here were produced by executing the app's own
// bytecode and are pinned by `testdata/vendor-desktop-1.1.5.json`
// (`vendor-parity.test.mjs`, regenerated by `helper/raccoon-vendor-fixture.mjs`).
//
// This file is the reproduction. It holds four things the app does and the
// plugin did not: the SDK's `X-Stainless-*` set, the app's `x-client-*`
// identity, the `X-RACCOON-*` turn headers, and the per-model thinking
// parameters (`_apply_thinking_params`, box_agent/llm/openai_client.py:127),
// which are not one shape but six.
//
// A file of its own for the same reason as `workbuddy/codebuddy.mjs`: upstream
// owns `index.mjs`, and none of this may sit in the way of merging it.
//
// Where each value comes from, in the app:
//   X-Stainless-*      openai/_base_client.py platform_headers() (:686)
//   x-client-*         build/electron/main/agent/boxAgentManager.js
//                      buildBoxAgentClientInfo(), then
//                      box_agent/client_info.py headers_for_url() (:84)
//   X-RACCOON-*        box_agent/llm/base.py _agent_headers() (:174)
//   X-Org-Code         box_agent/llm/base.py _auth_headers() (:83),
//                      box_agent/auth.py read_auth_org_code() (:140)
//   thinking           box_agent/llm/openai_client.py (:127)
//   stream_options     box_agent/llm/openai_client.py _request_body_params()
//                      (:617)
import { createHash, randomUUID } from "node:crypto"
import { release as osRelease } from "node:os"

// The app this reproduces. Bumping any of these means regenerating the
// fixture, which is what `--check` in the helper is for.
export const VENDOR = {
  app: "@raccoon/office-desktop",
  appVersion: "1.1.5",
  channel: "official",
  // the CPython the app bundles (resources/box-agent-runtime/bin/_internal/
  // python312.dll names exactly one 3.12.x)
  pythonVersion: "3.12.13",
  // box_agent's openai dependency
  sdkVersion: "2.8.0",
}

// ── which hosts get an identity ────────────────────────────────────────────
//
// box_agent/client_info.py should_attach_client_headers(): the app names
// itself only to its own backend. The plugin keeps that rule and adds none of
// its own — RACCOON_CLIENT_HEADERS_HOSTS is for pointing
// RACCOON_LLM_BASE_URL at a relay, where the app's own name is still the one
// to send. Comma-separated, same shape as RACCOON_USER_AGENT.
const IDENTITY_HOST = "xiaohuanxiong.com"

function extraHosts() {
  return String(process.env.RACCOON_CLIENT_HEADERS_HOSTS ?? "")
    .split(",")
    .map((host) => host.trim().toLowerCase().replace(/\.+$/, ""))
    .filter(Boolean)
}

export function hostAcceptsIdentity(url) {
  let parsed
  try {
    parsed = new URL(String(url))
  } catch {
    return false
  }
  if (parsed.protocol !== "https:" && parsed.protocol !== "http:") return false
  const host = parsed.hostname.toLowerCase().replace(/\.+$/, "")
  if (host === IDENTITY_HOST || host.endsWith(`.${IDENTITY_HOST}`)) return true
  return extraHosts().includes(host)
}

// ── X-Stainless-* ──────────────────────────────────────────────────────────

// platform.machine(), as CPython answers it on each of the app's platforms.
// This is the string get_architecture() branches on, not Node's process.arch:
// Windows says "AMD64", which is why the app's Windows build reports
// `other:amd64` rather than `x64`.
function machineOf(platform, arch) {
  if (platform === "win32") return arch === "arm64" ? "ARM64" : arch === "arm" ? "ARM" : arch === "ia32" ? "x86" : "AMD64"
  if (platform === "darwin") return arch === "arm64" ? "arm64" : "x86_64"
  return arch === "arm64" ? "aarch64" : arch === "arm" ? "armv7l" : "x86_64"
}

// openai/_base_client.py get_architecture() (:1992): three mappings, then
// OtherArch — whose __str__ is "other:<name>", so anything unmapped still
// names itself. Windows AMD64 falls through all three.
export function stainlessArch(platform = process.platform, arch = process.arch) {
  const machine = machineOf(platform, arch).toLowerCase()
  if (machine === "arm64" || machine === "aarch64") return "arm64"
  if (machine === "arm") return "arm"
  if (machine === "x86_64") return "x64"
  return machine ? `other:${machine}` : "unknown"
}

// get_platform() (:1912). The Linux branch asks distro.id() and only decides
// between "Linux" and other Linux distributions, all of which the SDK sends as
// "Linux" anyway. The rest is by symmetry with OtherArch and untested: no
// fixture host is on a platform the app ships for. Note the capital O —
// OtherPlatform spells itself "Other:", where OtherArch says "other:".
export function stainlessOs(platform = process.platform) {
  if (platform === "darwin") return "MacOS"
  if (platform === "win32") return "Windows"
  if (platform === "linux") return "Linux"
  if (platform === "freebsd") return "FreeBSD"
  if (platform === "openbsd") return "OpenBSD"
  return platform ? `Other:${platform}` : "Unknown"
}

export function stainlessHeaders({ platform = process.platform, arch = process.arch } = {}) {
  return {
    "X-Stainless-Lang": "python",
    "X-Stainless-Package-Version": VENDOR.sdkVersion,
    "X-Stainless-OS": stainlessOs(platform),
    "X-Stainless-Arch": stainlessArch(platform, arch),
    "X-Stainless-Runtime": "CPython",
    "X-Stainless-Runtime-Version": VENDOR.pythonVersion,
  }
}

// ── x-client-* ─────────────────────────────────────────────────────────────
//
// Two halves. The JS side builds the five fields
// (boxAgentManager.js buildBoxAgentClientInfo), the Python side turns them
// into headers and drops what it cannot send
// (box_agent/client_info.py headers_for_url, :84).

const MAX_HEADER_VALUE = 256

// _clean_header_value() (:33): not a string, or blank, or not ASCII, or any
// control character, and the whole value is gone — not escaped, not truncated
// down to something sendable.
function cleanHeaderValue(value) {
  if (typeof value !== "string") return ""
  const cleaned = value.trim()
  if (!cleaned || !/^[\x00-\x7f]*$/.test(cleaned)) return ""
  if (/[\x00-\x1f\x7f]/.test(cleaned)) return ""
  return cleaned.slice(0, MAX_HEADER_VALUE)
}

// normalizeDesktopPlatform(): the OS and arch as the app spells them, which is
// not the same spelling the SDK uses next door. `desktop-windows-x64` here,
// `other:amd64` there, from the same machine.
export function desktopPlatform(platform = process.platform, arch = process.arch) {
  const os = platform === "darwin" ? "macos" : platform === "win32" ? "windows" : platform === "linux" ? "linux" : "unknown"
  const cpu = arch === "ia32" ? "x86" : arch === "x64" || arch === "arm" || arch === "arm64" ? arch : "unknown"
  return `desktop-${os}-${cpu}`
}

// normalizeClientVersion(): one leading v, and nothing else is checked here.
// The three-part test happens on the Python side, which throws the header away
// when it fails.
export function clientVersion(version = VENDOR.appVersion) {
  const normalized = String(version ?? "").trim()
  if (!normalized) return ""
  return normalized.startsWith("v") ? normalized : `v${normalized}`
}

// headers_for_url(): the version alone is validated (strictly three numeric
// parts), so `1.1.5-beta` costs the header while the other four still go.
const VERSION_RE = /^v?(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)$/

export function clientIdentityHeaders({
  url,
  platform = process.platform,
  arch = process.arch,
  osVersion = osRelease(),
  version = VENDOR.appVersion,
  name = VENDOR.app,
  channel = VENDOR.channel,
  deviceId = "",
} = {}) {
  if (url !== undefined && !hostAcceptsIdentity(url)) return {}
  const cleanedVersion = cleanHeaderValue(clientVersion(version))
  const values = [
    ["x-client-name", cleanHeaderValue(name) || "raccoon"],
    ["x-client-platform", cleanHeaderValue(desktopPlatform(platform, arch)) || "unknown"],
    ["x-client-version", VERSION_RE.test(cleanedVersion) ? `v${cleanedVersion.replace(/^v/, "")}` : ""],
    // Electron's getSystemVersion(), which is the OS release string; the
    // fallback (os.release()) is the same string on Windows and Linux and the
    // Darwin kernel version on macOS, where the app would have said the
    // product version.
    ["x-client-os-version", cleanHeaderValue(osVersion)],
    ["x-client-channel", cleanHeaderValue(channel)],
    ["x-client-device-id", cleanHeaderValue(deviceId)],
  ]
  const headers = {}
  for (const [header, value] of values) {
    // the vendor's own rule: a value that cleans to nothing is not sent at all
    if (value) headers[header] = value
  }
  return headers
}

// ── X-RACCOON-* ────────────────────────────────────────────────────────────
//
// box_agent/llm/base.py _agent_headers() (:174). Four headers, each dropped
// when blank, and a non-ASCII value is not dropped but encoded — HTTP carries
// it as bytes, so a Chinese session title still arrives.
export function agentHeaders({ sessionId = "", turnId = "", title = "", callKind = "" } = {}) {
  const values = [
    ["X-RACCOON-Session-ID", sessionId],
    ["X-RACCOON-Turn-ID", turnId],
    ["X-RACCOON-Title", title],
    ["X-RACCOON-Call-Kind", callKind],
  ]
  const headers = {}
  for (const [header, raw] of values) {
    const value = typeof raw === "string" ? raw.trim() : ""
    if (value) headers[header] = value
  }
  return headers
}

// The plugin sees no session, so one is derived from the conversation: the
// same first message gives the same UUID on every turn of it, which is what
// the app's own session id does. A UUID v4 shape, because the id is one.
export function conversationSessionId(payload) {
  const messages = Array.isArray(payload?.messages) ? payload.messages : []
  const first = messages.find((m) => m && m.role !== "system")
  if (!first) return randomUUID()
  const h = createHash("sha256").update(JSON.stringify([first.role, first.content ?? null])).digest("hex")
  const variant = ((parseInt(h[16], 16) & 0x3) | 0x8).toString(16)
  return `${h.slice(0, 8)}-${h.slice(8, 12)}-4${h.slice(13, 16)}-${variant}${h.slice(17, 20)}-${h.slice(20, 32)}`
}

// ── X-Org-Code ─────────────────────────────────────────────────────────────
//
// box_agent/auth.py read_auth_org_code() (:140): the auth state's
// office_identity, unless it is blank, "personal", or not ASCII. A personal
// account sends no such header, which is why its absence is the common case.
export function readOrgCode(auth) {
  const identity = auth?.office_identity
  if (typeof identity !== "string") return ""
  const code = identity.trim()
  if (!code || code === "personal" || !/^[\x00-\x7f]*$/.test(code)) return ""
  return code
}

// ── thinking ───────────────────────────────────────────────────────────────
//
// _apply_thinking_params (openai_client.py:127) is not one rule but six, and
// which one applies is decided by the model id. The plugin used to write
// extra_body.thinking.type for everything, which is right for deepseek and
// doubao and wrong for the rest: qwen reads enable_thinking, the
// kimi/glm/sensenova families take reasoning_effort, and the gemini and gpt-6
// families have models that must not be told "off" at all.
//
// The vendor writes these into `params['extra_body']`, and that container is
// not a wire field — the SDK's `make_request_options` lifts it to `extra_json`
// and `_build_request` merges it into the body, so one level disappears. What
// the fixture records, and what this file reproduces, is post-merge: qwen's
// `enable_thinking` sits at the top, and only deepseek's thinking — which the
// vendor wraps one deeper via `_litellm_extra_body` — stays under extra_body.

const GPT6_RE = /(?:^|\/)gpt-6-(?:sol|luna)(?:$|[-/:])/
const KIMI_K3_RE = /(?:^|\/)(?:sn-)?kimi-k3(?:$|[-:])/
const GLM_5_3_MARKERS = ["glm-5-3", "glm-5.3"]
const GEMINI_NO_DISABLE_MARKERS = ["gemini-2.5-pro", "gemini-3.1-pro"]
const SENSENOVA_PREFIXES = ["sensenova-", "sn-sensenova-"]
const SENSENOVA_LOW_DEFAULT_MODELS = new Set(["sensenova-flash-lite-20260727-v39-fp8-step4k-dpov2-mtp"])

const isSensenova = (model) => SENSENOVA_PREFIXES.some((prefix) => model.startsWith(prefix))

/** The level the caller asked for, before any per-model rewriting. */
export function thinkingLevelOf(body) {
  const read = (value) => {
    if (typeof value === "string") return normalizeThinking(value)
    if (value && typeof value === "object" && typeof value.type === "string") return normalizeThinking(value.type)
    return ""
  }
  const direct = read(body?.thinking) || read(body?.extra_body?.thinking)
  if (direct) return direct
  if (typeof body?.enable_thinking === "boolean") return body.enable_thinking ? "enabled" : "disabled"
  const nested = body?.extra_body?.enable_thinking
  if (typeof nested === "boolean") return nested ? "enabled" : "disabled"
  if (typeof body?.reasoning_effort === "string") return effortToThinking(body.reasoning_effort)
  return ""
}

export function normalizeThinking(value) {
  const v = String(value).trim().toLowerCase()
  if (v === "enabled" || v === "enable" || v === "on" || v === "true") return "enabled"
  if (v === "disabled" || v === "disable" || v === "off" || v === "false" || v === "none") return "disabled"
  return ""
}

// What an effort means when it arrives instead of a switch. "low" is still on:
// for the kimi and glm families the app itself sends reasoning_effort low to
// mean thinking off, so the mapping is not symmetric and low cannot be read as
// disabled.
export function effortToThinking(effort) {
  const v = String(effort).trim().toLowerCase()
  if (v === "none" || v === "off" || v === "minimal") return "disabled"
  return "enabled"
}

function hasFunctionTools(body) {
  return Array.isArray(body?.tools) && body.tools.some((tool) => tool && tool.type === "function")
}

/**
 * Rewrite a chat body's thinking parameters into what the app sends for this
 * model. Returns true when the body changed.
 *
 * The app always knows whether thinking is on. The plugin does not: it only
 * sees what the calling agent asked for, so with no intent in the body this
 * leaves the body alone rather than inventing `reasoning_effort: high` for
 * every request.
 */
export function dispatchThinking(body) {
  if (!body || typeof body !== "object") return false
  const level = thinkingLevelOf(body)
  if (!level) return false
  const on = level === "enabled"
  const model = String(body.model ?? "").trim().toLowerCase()

  // The vendor builds its params from nothing, so it never has to remove
  // anything. The plugin's body arrives with whatever the agent put there, and
  // a body carrying both extra_body.thinking.type and reasoning_effort is a
  // body the vendor never sends — so the shape is decided first, then written,
  // and every branch ends with the same "these three keys, or none of them".
  writeThinkingShape(body, thinkingShape(model, on, body))
  return true
}

function thinkingShape(model, on, body) {
  // a gpt-6 with function tools is told "none" either way: the model will not
  // take tools and reasoning in one turn
  if (GPT6_RE.test(model) && hasFunctionTools(body)) return { effort: "none" }
  if (KIMI_K3_RE.test(model)) return { effort: on ? "high" : "low" }
  if (GLM_5_3_MARKERS.some((marker) => model.includes(marker))) return { effort: on ? "high" : "low" }
  if (model.includes("deepseek") || model.includes("doubao")) {
    // the vendor sets params['extra_body'] = _litellm_extra_body({thinking}),
    // and that helper wraps it one deeper so that the SDK's own unwrapping
    // lands it at `extra_body.thinking` on the wire
    return { container: { extra_body: { thinking: { type: on ? "enabled" : "disabled" } } } }
  }
  if (model.includes("qwen")) {
    // params['extra_body'] = {'enable_thinking': bool}: the SDK folds the
    // container flat, so this arrives as a plain top-level field
    return { container: { enable_thinking: on } }
  }
  if (model.includes("gemini")) {
    if (on) return { effort: "high" }
    // these two reject being switched off, so the vendor names no level for
    // them at all — the branch returns before it writes anything
    if (GEMINI_NO_DISABLE_MARKERS.some((marker) => model.includes(marker))) return {}
    return { effort: "none" }
  }
  if (on) return { effort: "high" }
  if (isSensenova(model)) {
    return { effort: SENSENOVA_LOW_DEFAULT_MODELS.has(model) ? "low" : "none" }
  }
  // off, and no family that knows what off means for it: the vendor says
  // nothing, which is a shape too — the keys come out and nothing goes in
  return {}
}

function writeThinkingShape(body, shape) {
  // the three carriers come out wherever the agent left them, because a body
  // holding two of them at once is one the vendor never builds
  delete body.thinking
  delete body.enable_thinking
  delete body.reasoning_effort
  if (body.extra_body && typeof body.extra_body === "object") {
    delete body.extra_body.thinking
    delete body.extra_body.enable_thinking
    delete body.extra_body.reasoning_effort
    if (Object.keys(body.extra_body).length === 0) delete body.extra_body
  }
  if (shape.effort) body.reasoning_effort = shape.effort
  // the container is params-level `extra_body`, which the SDK merges into the
  // body one level up; folding it here is that merge
  for (const [key, value] of Object.entries(shape.container ?? {})) {
    if (key === "extra_body") body.extra_body = { ...(body.extra_body ?? {}), ...value }
    else body[key] = value
  }
}

// ── stream_options ─────────────────────────────────────────────────────────
//
// _request_body_params (openai_client.py:617) asks for usage on every stream:
// `params.update(stream=True, stream_options={'include_usage': True})`. The
// plugin's SSE reader ignores the extra chunk, so this costs nothing and makes
// the body match.
export function addStreamOptions(body) {
  if (!body || typeof body !== "object") return false
  if (body.stream !== true) return false
  const now = body.stream_options
  if (now && typeof now === "object" && now.include_usage === true) return false
  body.stream_options = { ...(now && typeof now === "object" ? now : {}), include_usage: true }
  return true
}

// ── the whole header set ───────────────────────────────────────────────────

/**
 * Add the app's identity to a chat request's headers, returning a new Headers.
 *
 * Everything here is additive: a header the host already set is left alone,
 * because the host's value is the one something chose. The exception is
 * `accept-encoding`, which is set rather than added — see KNOWN_DIVERGENCES.
 *
 * The copy is not incidental: a Headers handed to fetch may be one the SDK
 * reuses across requests, and writing the app's identity into it would carry
 * that identity to the next call as well.
 */
export function wireHeaders(headers, { url, body, orgCode = "", sessionId, turnId, title, callKind } = {}) {
  const target = new Headers(headers ?? {})
  if (!hostAcceptsIdentity(url)) return target

  const setIfAbsent = (name, value) => {
    if (!target.has(name)) target.set(name, value)
  }
  for (const [name, value] of Object.entries(stainlessHeaders())) setIfAbsent(name, value)
  for (const [name, value] of Object.entries(clientIdentityHeaders({ url, osVersion: osRelease() }))) {
    setIfAbsent(name, value)
  }
  const agent = agentHeaders({
    sessionId: sessionId ?? (body ? conversationSessionId(body) : ""),
    turnId: turnId ?? randomUUID(),
    title,
    callKind,
  })
  for (const [name, value] of Object.entries(agent)) setIfAbsent(name, value)
  if (orgCode) setIfAbsent("X-Org-Code", orgCode)

  // httpx's own defaults (httpx/_client.py ACCEPT_ENCODING, and the keep-alive
  // it sets on every request), which the app never overrides. Node's fetch
  // would otherwise advertise br/zstd. `connection` is a forbidden header name
  // in the Fetch spec: a transport that enforces the spec strips it silently,
  // so setting it costs nothing and matches the app wherever it survives.
  target.set("Accept-Encoding", "gzip, deflate")
  target.set("Connection", "keep-alive")
  return target
}

// ── what this cannot reproduce ─────────────────────────────────────────────
//
// Kept as data so that `vendor-parity.test.mjs` can fail when one is fixed
// without being struck off: the list is a claim about the code, and the test
// checks the claim against the code rather than trusting it. What is listed
// here is what `wireHeaders` deliberately does not set.
export const KNOWN_DIVERGENCES = {
  host: "the Host header is the URL's, and a relay's URL is not the app's",
  "content-length": "the body is not byte-identical (the plugin's max_tokens floor, the agent's own fields)",
}
